using Microsoft.AspNetCore.Http.HttpResults;

public static class OrderEndpoints
{
    public static RouteGroupBuilder MapOrders(this RouteGroupBuilder group)
    {
        group.MapGet("/{id:int}", GetOrder);
        group.MapPost("/", CreateOrder);
        return group;
    }

    // all possible responses: checked by the compiler, read by OpenAPI
    static Results<Ok<Order>, NotFound> GetOrder(int id, OrderStore store) =>
        store.Find(id) is { } order
            ? TypedResults.Ok(order)
            : TypedResults.NotFound();

    static Created<Order> CreateOrder(Order order, OrderStore store)
    {
        store.Add(order);
        return TypedResults.Created($"/api/orders/{order.Id}", order);
    }
}
